package init

import (
	"fmt"
	"path/filepath"
	"strings"

	"netrave/internal/platform"
)

// OpenRC uses the standard /etc/init.d script layout and rc-service.
type OpenRC struct{ Base }

func (o *OpenRC) Kind() platform.InitKind { return platform.InitOpenRC }

func (o *OpenRC) UnitPath() string {
	return filepath.Join("/etc/init.d", o.Config.Name)
}

func (o *OpenRC) Install(cfg ServiceConfig) error {
	script := fmt.Sprintf(`#!/sbin/openrc-run
# Generated by netrave installer.
name="%s"
description="NetRave virtual network labs"
command="%s"
command_args="daemon --config %s --foreground"
command_user="root:root"
command_background=true
pidfile="/run/%s/daemon.pid"
directory="%s"
output_log="%s"
error_log="%s"

depend() {
    need net
    after firewall
}

start_pre() {
    checkpath --directory --mode 0750 --owner root:root /run/%s
}
`, cfg.Name, cfg.Binary, cfg.ConfigFile, cfg.Name, cfg.DataDir, cfg.LogFile, cfg.LogFile, cfg.Name)
	if err := o.writeFile(o.UnitPath(), 0o755, script); err != nil {
		return err
	}
	return nil
}

func (o *OpenRC) Remove() error {
	_ = o.Disable()
	_ = o.Stop()
	return o.remove(o.UnitPath())
}

func (o *OpenRC) Enable() error  { return o.run("rc-update", "add", o.Config.Name, "default") }
func (o *OpenRC) Disable() error { return o.run("rc-update", "del", o.Config.Name, "default") }
func (o *OpenRC) Start() error   { return o.run("rc-service", o.Config.Name, "start") }
func (o *OpenRC) Stop() error    { return o.run("rc-service", o.Config.Name, "stop") }
func (o *OpenRC) Restart() error { return o.run("rc-service", o.Config.Name, "restart") }

func (o *OpenRC) Status() (string, error) {
	ctx, cancel := contextWithTimeout()
	defer cancel()
	output, err := o.Runner.Run(ctx, "rc-service", o.Config.Name, "status")
	if err != nil {
		return strings.TrimSpace(output), nil
	}
	return strings.TrimSpace(output), nil
}

func (o *OpenRC) Logs(lines int) (string, error) { return tailFile(o.Config.LogFile, lines) }

func (o *OpenRC) String() string { return "openrc" }
